    12  static int handle_data_frame(h2o_http2_conn_t *conn, h2o_http2_frame_t *frame, const char **err_desc)
    13  {
    14      h2o_http2_data_payload_t payload;
    15      h2o_http2_stream_t *stream;
    16      int ret;
    17
    18      if ((ret = h2o_http2_decode_data_payload(&payload, frame, err_desc)) != 0)
    19          return ret;
    20
    21      /* update connection-level window */
    22      h2o_http2_window_consume_window(&conn->_input_window, frame->length);
    23      if (h2o_http2_window_get_avail(&conn->_input_window) <= H2O_HTTP2_SETTINGS_HOST_CONNECTION_WINDOW_SIZE / 2)
    24          send_window_update(conn, 0, &conn->_input_window,
    25                             H2O_HTTP2_SETTINGS_HOST_CONNECTION_WINDOW_SIZE - h2o_http2_window_get_avail(&conn->_input_window));
    26
    27      /* check state */
    28      if ((stream = h2o_http2_conn_get_stream(conn, frame->stream_id)) == NULL) {
    29          if (frame->stream_id <= conn->pull_stream_ids.max_open) {
    30              stream_send_error(conn, frame->stream_id, H2O_HTTP2_ERROR_STREAM_CLOSED);
    31              return 0;
    32          } else {
    33              *err_desc = "invalid DATA frame";
    34              return H2O_HTTP2_ERROR_PROTOCOL;
    35          }
    36      }
    37      if (stream->state != H2O_HTTP2_STREAM_STATE_RECV_BODY) {
    38          stream_send_error(conn, frame->stream_id, H2O_HTTP2_ERROR_STREAM_CLOSED);
    39          h2o_http2_stream_reset(conn, stream);
    40          return 0;
    41      }
    42
    43      /* update stream-level window (doing it here could end up in sending multiple WINDOW_UPDATE frames if the receive window is
    44       * fully-used, but no need to worry; in such case we'd be sending ACKs at a very fast rate anyways) */
    45      h2o_http2_window_consume_window(&stream->input_window.window, frame->length);
    46      if (frame->length != payload.length)
    47          update_stream_input_window(conn, stream, frame->length - payload.length);
    48
    49      /* actually handle the input */
    50      if (payload.length != 0 || (frame->flags & H2O_HTTP2_FRAME_FLAG_END_STREAM) != 0)
    51          handle_request_body_chunk(conn, stream, h2o_iovec_init(payload.data, payload.length),
    52                                    (frame->flags & H2O_HTTP2_FRAME_FLAG_END_STREAM) != 0);
    53
    54      return 0;
    55  }
