    57  static int handle_headers_frame(h2o_http2_conn_t *conn, h2o_http2_frame_t *frame, const char **err_desc)
    58  {
    59      h2o_http2_headers_payload_t payload;
    60      h2o_http2_stream_t *stream;
    61      int ret;
    62
    63      /* decode */
    64      if ((ret = h2o_http2_decode_headers_payload(&payload, frame, err_desc)) != 0)
    65          return ret;
    66      if ((frame->stream_id & 1) == 0) {
    67          *err_desc = "invalid stream id in HEADERS frame";
    68          return H2O_HTTP2_ERROR_PROTOCOL;
    69      }
    70      if (!(conn->pull_stream_ids.max_open < frame->stream_id)) {
    71          if ((stream = h2o_http2_conn_get_stream(conn, frame->stream_id)) != NULL &&
    72              stream->state == H2O_HTTP2_STREAM_STATE_RECV_BODY) {
    73              /* is a trailer */
    74              if ((frame->flags & H2O_HTTP2_FRAME_FLAG_END_STREAM) == 0) {
    75                  *err_desc = "trailing HEADERS frame MUST have END_STREAM flag set";
    76                  return H2O_HTTP2_ERROR_PROTOCOL;
    77              }
    78              stream->req.entity = h2o_iovec_init(stream->_req_body.body->bytes, stream->_req_body.body->size);
    79              if ((frame->flags & H2O_HTTP2_FRAME_FLAG_END_HEADERS) == 0)
    80                  goto PREPARE_FOR_CONTINUATION;
    81              return handle_trailing_headers(conn, stream, payload.headers, payload.headers_len, err_desc);
